import{_ as a,o as e,c as s,a3 as i}from"./chunks/framework.CVt6dz2a.js";const m=JSON.parse('{"title":"EP.06 材质与 PBR 光影","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.06-material-pbr.md","filePath":"comics/EP.06-material-pbr.md","lastUpdated":1792595797000}'),n={name:"comics/EP.06-material-pbr.md"};function r(o,t,l,d,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="ep-06-材质与-pbr-光影" tabindex="-1">EP.06 材质与 PBR 光影 <a class="header-anchor" href="#ep-06-材质与-pbr-光影" aria-label="Permalink to &quot;EP.06 材质与 PBR 光影&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/06-material/basics">6.1 基础入门：四种常用材质对比</a> 延伸阅读：<a href="./../guide/06-material/advanced">进阶篇</a> · <a href="./../guide/06-material/practice">实战篇</a> 动手演示：<a href="./../public/demos/material/material-compare.html">material-compare 四材质同光对比</a> · <a href="./../public/demos/material/physical-env.html">physical-env 环境反射实验</a> · <a href="./../public/demos/material/material-lab.html">material-lab 材质实验室</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君把 <code>metalness</code> 拉到 1 想做不锈钢球，结果球黑得像个黑洞，加灯也救不回来。</td></tr><tr><td>② 揭秘</td><td>码叔摆出四种材质：Basic 不吃光、Lambert 只有漫反射、Phong 有锐利高光、Standard 走 PBR；金属的颜色几乎全部来自<strong>反射环境</strong>。</td></tr><tr><td>③ 实证</td><td>像素酱用 <code>PMREMGenerator</code> 烘焙一张 <code>RoomEnvironment</code> 环境贴图赋给 <code>scene.environment</code>，金属球瞬间映出整个房间，粗糙度旋钮让反射从镜面到磨砂连续变化。</td></tr><tr><td>④ 结案</td><td>码叔总结：PBR 两个旋钮 roughness/metalness 描述物理，但反射需要&quot;可反射的内容&quot;。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-四种材质速查" tabindex="-1">① 四种材质速查 <a class="header-anchor" href="#_1-四种材质速查" aria-label="Permalink to &quot;① 四种材质速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>材质</th><th>受灯光</th><th>特点</th><th>典型用途</th></tr></thead><tbody><tr><td>MeshBasicMaterial</td><td>❌</td><td>纯色/贴图，无明暗，最便宜</td><td>天空盒、UI、发光条、调试</td></tr><tr><td>MeshLambertMaterial</td><td>✅</td><td>只有漫反射，无高光</td><td>低多边形、墙面、远景</td></tr><tr><td>MeshPhongMaterial</td><td>✅</td><td>漫反射 + shininess 锐利高光</td><td>老式光泽塑料</td></tr><tr><td>MeshStandardMaterial</td><td>✅</td><td>PBR：roughness/metalness</td><td><strong>现代项目默认</strong></td></tr></tbody></table><p>Basic 不是&quot;最差材质&quot;：凡是本来就不该受光的东西（星空、灯条、包围盒），它是最正确最便宜的选择。</p><h3 id="_2-pbr-两个核心旋钮" tabindex="-1">② PBR 两个核心旋钮 <a class="header-anchor" href="#_2-pbr-两个核心旋钮" aria-label="Permalink to &quot;② PBR 两个核心旋钮&quot;">​</a></h3><ul><li><strong>roughness 粗糙度</strong>：0 = 镜面反射，1 = 完全粗糙的漫反射；</li><li><strong>metalness 金属度</strong>：0 = 非金属（塑料/木材/漆面），1 = 纯金属。</li></ul><p>金属的特殊性：金属表面几乎不返回漫反射颜色，看到的颜色主要是对环境的反射。场景里<strong>没有环境贴图时，金属球没有任何东西可反射，于是输出黑色</strong>——这不是 bug。</p><h3 id="_3-roomenvironment-给-pbr-一面-镜子" tabindex="-1">③ RoomEnvironment：给 PBR 一面&quot;镜子&quot; <a class="header-anchor" href="#_3-roomenvironment-给-pbr-一面-镜子" aria-label="Permalink to &quot;③ RoomEnvironment：给 PBR 一面&quot;镜子&quot;&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { RoomEnvironment } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;three/addons/environments/RoomEnvironment.js&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pmrem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PMREMGenerator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(renderer)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scene.environment </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pmrem.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fromScene</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RoomEnvironment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.04</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).texture</span></span></code></pre></div><ul><li><code>scene.environment</code> 为所有 PBR 材质提供<strong>基于图像的照明（IBL）</strong>，不产生可见背景；</li><li>PMREM 预过滤环境贴图，让不同 roughness 都能得到正确模糊度的反射；</li><li>想让环境图同时成为背景，再设 <code>scene.background = envTexture</code>。</li></ul><h3 id="_4-能量守恒与直觉调试" tabindex="-1">④ 能量守恒与直觉调试 <a class="header-anchor" href="#_4-能量守恒与直觉调试" aria-label="Permalink to &quot;④ 能量守恒与直觉调试&quot;">​</a></h3><p>roughness 越小，高光/反射越集中清晰；越大越弥散。调材质顺序建议：先给 environment，再定 metalness（金属/非金属是离散选择），最后磨 roughness。拿不准时用同色同光对比四个材质，差异只来自光照模型。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：Standard 材质总是灰蒙蒙？</strong> 高粗糙度表面缺少环境反射内容，补 <code>scene.environment</code> 立刻改善。</li><li><strong>Q：Phong 的 shininess 和 roughness 是一回事吗？</strong> 方向相反且模型不同：shininess 越大高光越锐利，但 Phong 非物理模型；新项目统一用 Standard 的 roughness。</li><li><strong>Q：MeshPhysicalMaterial 与 Standard 区别？</strong> Physical 扩展 clearcoat（清漆）、transmission（透射/玻璃）、sheen（布料绒光）等，成本更高，按需使用。</li><li><strong>Q：环境贴图需要外部 HDR 图片吗？</strong> 不需要，<code>RoomEnvironment</code> 是纯程序化的室内环境；写实项目再换 HDRLoader 加载 .hdr/.exr。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>metalness=1 的球体在纯黑场景中为什么是黑的？最小修复是什么？</li><li>做一块&quot;完全粗糙的红砖墙&quot;和&quot;一面梳妆镜&quot;，roughness 分别接近几？</li><li><code>scene.environment</code> 与 <code>scene.background</code> 的作用有何不同？</li></ol><details><summary>答案</summary><ol><li>金属的可见颜色主要来自<strong>对环境的镜面反射</strong>，场景没有任何环境光/环境贴图时无内容可反射，因此为黑。最小修复：用 <strong>PMREMGenerator + RoomEnvironment</strong> 设置 <code>scene.environment</code>。</li><li>砖墙 roughness 接近 <strong>1</strong>（漫反射、无清晰反光）；镜子接近 <strong>0</strong>（镜面全反射）。</li><li><code>scene.environment</code> 只提供 <strong>IBL 照明与反射来源</strong>，画面背景不变；<code>scene.background</code> 决定<strong>画布背景</strong>显示什么（纯色、贴图或天空盒）。两者可以分别设置。</li></ol></details>`,21)])])}const k=a(n,[["render",r]]);export{m as __pageData,k as default};
